 "content": "from collections import deque


def transform(grid):
    """Alternate isolated color-2 objects left-to-right, ending with color 8."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append(cells)

    # The rightmost object is always recolored to 8; alternate moving left.
    objects.sort(key=lambda cells: min(c for _, c in cells))
    for i, cells in enumerate(objects):
        if (len(objects) - 1 - i) % 2 == 0:
            for r, c in cells:
                out[r][c] = 8
    return out
